    "src/cart.ts": "export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

export interface CartCalculation {
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
}

function roundTo2Decimals(value: number): number {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

export function calculateCartTotal(
  items: CartItem[],
  couponCode?: string,
  taxRate: number = 0.08
): CartCalculation {
  const subtotalRaw = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  const subtotal = roundTo2Decimals(subtotalRaw);

  if (subtotalRaw === 0) {
    return {
      subtotal: 0,
      discount: 0,
      tax: 0,
      total: 0,
    };
  }

  let discount = 0;
  if (couponCode === "SAVE10") {
    discount = roundTo2Decimals(subtotal * 0.1);
  } else if (couponCode === "FLAT5") {
    discount = roundTo2Decimals(Math.min(5, subtotal));
  }

  const discountedSubtotal = Math.max(0, subtotal - discount);
  const tax = roundTo2Decimals(discountedSubtotal * taxRate);
  const total = roundTo2Decimals(discountedSubtotal + tax);

  return {
    subtotal,
    discount,
    tax,
    total,
  };
